CREATE TYPE ledger.entry_side AS ENUM ('debit', 'credit');
CREATE TYPE ledger.posting_state AS ENUM ('draft', 'posted', 'void');
CREATE TYPE ledger.account_ref AS (
    code TEXT,
    display_name TEXT
);

CREATE TABLE ledger.books (
    tenant_id BIGINT NOT NULL,
    book_id BIGINT GENERATED ALWAYS AS IDENTITY,
    code TEXT NOT NULL,
    state ledger.posting_state NOT NULL DEFAULT 'draft',
    PRIMARY KEY (tenant_id, book_id),
    CONSTRAINT uq_books_code UNIQUE (tenant_id, code)
);

CREATE TABLE ledger.accounts (
    tenant_id BIGINT NOT NULL,
    book_id BIGINT NOT NULL,
    account_id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    account ledger.account_ref,
    normal_side ledger.entry_side NOT NULL,
    PRIMARY KEY (tenant_id, book_id, account_id),
    CONSTRAINT fk_accounts_book
        FOREIGN KEY (tenant_id, book_id)
        REFERENCES ledger.books(tenant_id, book_id)
);

CREATE TABLE ledger.journal_entries (
    tenant_id BIGINT NOT NULL,
    book_id BIGINT NOT NULL,
    entry_id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    external_ref TEXT NOT NULL,
    state ledger.posting_state NOT NULL DEFAULT 'draft',
    PRIMARY KEY (tenant_id, book_id, entry_id),
    CONSTRAINT uq_entries_external UNIQUE (tenant_id, book_id, external_ref),
    CONSTRAINT fk_entries_book
        FOREIGN KEY (tenant_id, book_id)
        REFERENCES ledger.books(tenant_id, book_id)
);

CREATE TABLE ledger.postings (
    tenant_id BIGINT NOT NULL,
    book_id BIGINT NOT NULL,
    entry_id BIGINT NOT NULL,
    line_no INT NOT NULL,
    account_id BIGINT NOT NULL,
    side ledger.entry_side NOT NULL,
    amount NUMERIC(14, 2) NOT NULL CHECK (amount >= 0),
    PRIMARY KEY (tenant_id, book_id, entry_id, line_no),
    CONSTRAINT fk_postings_entry
        FOREIGN KEY (tenant_id, book_id, entry_id)
        REFERENCES ledger.journal_entries(tenant_id, book_id, entry_id),
    CONSTRAINT fk_postings_account
        FOREIGN KEY (tenant_id, book_id, account_id)
        REFERENCES ledger.accounts(tenant_id, book_id, account_id)
);

CREATE INDEX idx_entries_state_external
    ON ledger.journal_entries (state, external_ref)
    WHERE state <> 'void';

CREATE INDEX idx_postings_account_side
    ON ledger.postings (account_id, side);
